import{_ as t,o,c as n,ah as a}from"./chunks/framework.GjtxVZ8F.js";const i="/projects/WonderMV/en/latest/assets/image2.CkFrfK4B.png",r="/projects/WonderMV/en/latest/assets/image3.B4rytlDL.png",s="/projects/WonderMV/en/latest/assets/image4.DIzZaLH6.png",l="/projects/WonderMV/en/latest/assets/image5.CsAMDzu9.png",_=JSON.parse('{"title":"2. Light Up K210","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2.Light_Up_K210.md","filePath":"docs/2.Light_Up_K210.md"}'),h={name:"docs/2.Light_Up_K210.md"};function c(p,e,d,g,u,m){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="_2-light-up-k210" tabindex="-1">2. Light Up K210 <a class="header-anchor" href="#_2-light-up-k210" aria-label="Permalink to &quot;2. Light Up K210&quot;">​</a></h1><p>The following steps will illuminate the visual module screen and test the touch screen functionality using buttons. The operation steps are as follows:</p><h2 id="_2-1-module-connection" tabindex="-1">2.1 Module Connection <a class="header-anchor" href="#_2-1-module-connection" aria-label="Permalink to &quot;2.1 Module Connection&quot;">​</a></h2><p>Connect the K210 Vision Module to the PC end using a Type-C data cable, as shown in the figure below:</p><img loading="lazy" height="753" width="946" class="common_img" src="'+i+'" style="width:600px;" alt="IMG_256"><p>Because the K210 visual module comes preloaded with firmware, when powered on, the screen of the K210 will light up, displaying the real-time feed from the camera.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>If the screen does not light up properly after connecting the power supply, please proceed to <a href="#anchor_2_3">2.3 Troubleshooting for Screen Not Lighting Up</a> for further investigation.</p></section><h2 id="_2-2-hardware-function-test" tabindex="-1">2.2 Hardware Function Test <a class="header-anchor" href="#_2-2-hardware-function-test" aria-label="Permalink to &quot;2.2 Hardware Function Test&quot;">​</a></h2><p>(1) Press the <strong>&#39;K1&#39;</strong> button. The fill light will illuminate. Press the <strong>&#39;K1&#39;</strong> button again, and the fill light will turn off.</p><img loading="lazy" height="272" width="443" class="common_img" src="'+r+'" style="width:500px;"><p>(2) Press the <strong>&#39;K2&#39;</strong> button. The blue LED light on the visual module will illuminate, and the current image will be frozen. At this point, you can draw lines on the screen with your finger. Press the <strong>&#39;K2&#39;</strong> button again to clear the lines, turn off the blue LED light, and resume normal display of the image.</p><img loading="lazy" height="559" width="780" class="common_img" src="'+s+'" style="width:500px;"><img loading="lazy" height="646" width="862" class="common_img" src="'+l+'" style="width:500px;"><p id="anchor_2_3"></p><h2 id="_2-3-troubleshooting-for-screen-not-lighting-up" tabindex="-1">2.3 Troubleshooting for Screen Not Lighting Up <a class="header-anchor" href="#_2-3-troubleshooting-for-screen-not-lighting-up" aria-label="Permalink to &quot;2.3 Troubleshooting for Screen Not Lighting Up&quot;">​</a></h2><p>If the screen does not light up after connection, please troubleshoot the following:</p><p>(1) Check if the USB cable is normal and securely plugged in.</p><p>(2) Verify that the K210 module requires a stable 5V power supply.</p><p>(3) If there are other .py programs downloaded onto the SD card, they will take priority in execution.</p><p>(4) The K210 module comes preloaded with firmware. If you has erased the firmware, please refer to <a href="./3.Getting_Ready.html#learn-factory-firmware-burning">3. Getting Ready-&gt;3.6 Learn Factory Firmware Burning</a> for re-flashing instructions.</p>',20)])])}const w=t(h,[["render",c]]);export{_ as __pageData,w as default};
